// Semáforo: vermelho, verde e amarelo em sequência
const int vermelho = 8;
const int amarelo = 9;
const int verde = 10;

void setup() {
  pinMode(vermelho, OUTPUT);
  pinMode(amarelo, OUTPUT);
  pinMode(verde, OUTPUT);
}

void loop() {
  digitalWrite(vermelho, HIGH);
  delay(3000);
  digitalWrite(vermelho, LOW);

  digitalWrite(verde, HIGH);
  delay(3000);
  digitalWrite(verde, LOW);

  digitalWrite(amarelo, HIGH);
  delay(1000);
  digitalWrite(amarelo, LOW);
}

exemplo:
// Mesma ideia, mas com uma função própria para não repetir código
const int vermelho = 8;
const int amarelo = 9;
const int verde = 10;

void acender(int pino, int tempo) {
  digitalWrite(pino, HIGH);
  delay(tempo);
  digitalWrite(pino, LOW);
}

void setup() {
  pinMode(vermelho, OUTPUT);
  pinMode(amarelo, OUTPUT);
  pinMode(verde, OUTPUT);
}

void loop() {
  acender(vermelho, 3000);
  acender(verde, 3000);
  acender(amarelo, 1000);
}
